(window.webpackJsonp=window.webpackJsonp||[]).push([[427],{756:function(e,r,t){"use strict";t.r(r);var n=t(33),a=Object(n.a)({},function(){var e=this,r=e.$createElement,t=e._self._c||r;return t("ContentSlotsDistributor",{attrs:{"slot-key":e.$parent.slotKey}},[t("h1",{attrs:{id:"termodynamik"}},[t("a",{staticClass:"header-anchor",attrs:{href:"#termodynamik","aria-hidden":"true"}},[e._v("#")]),e._v(" Termodynamik")]),e._v(" "),t("p",[e._v("Termodynamik handlar om energi. Eller rättare sagt, termodynamik är läran om energi och framförallt samspelet mellan värme och arbete. Arbete är inom fysiken den energimängd som omvandlas när en förflyttning sker under inverkan av en kraft. Termodynamiken som de flesta känner den kallas för den klassiska termodynamiken.")]),e._v(" "),t("p",[t("strong",[t("em",[e._v("Se filmen nedan om, Liten introduktion till termodynamik")])])]),e._v(" "),t("iframe",{attrs:{width:"560",height:"315",src:"https://www.youtube-nocookie.com/embed/P8b7L85Kyb0",frameborder:"0",allow:"accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""}}),e._v(" "),t("p",[e._v("Den klassiska termodynamiken visar på kopplingen mellan egenskaper som "),t("strong",[t("em",[e._v("temperatur")]),e._v(", "),t("em",[e._v("volym")])]),e._v(" och "),t("strong",[t("em",[e._v("tryck")])]),e._v(" hos system."),t("br")]),e._v(" "),t("p",[e._v("Termodynamikens grundprinciper har under åren kommit att formuleras i fyra huvudsatser, vilka beskriver olika aspekter av energins natur och hur olika former av energi kan interagera.")]),e._v(" "),t("p",[t("strong",[e._v("De fyra huvudsatserna är:")])]),e._v(" "),t("p",[t("a",{attrs:{href:"https://sv.wikipedia.org/wiki/Termodynamikens_nollte_huvudsats",target:"_blank",rel:"noopener noreferrer"}},[e._v("Termodynamikens nollte huvudsats"),t("OutboundLink")],1),e._v(", vilken utgör grunden för temperaturmätning. Termodynamikens nollte huvudsats säger att "),t("em",[e._v('"Två kroppar som var för sig är i termisk jämvikt med en tredje kropp, står även i termisk jämvikt med varandra')]),e._v('."')]),e._v(" "),t("p",[e._v("Detta innebär att två kroppar i termisk kontakt med varandra antar samma temperatur genom att värmeenergi i den varmare kroppen flödar till den kallare kroppen.")]),e._v(" "),t("p",[t("a",{attrs:{href:"https://sv.wikipedia.org/wiki/Energiprincipen",target:"_blank",rel:"noopener noreferrer"}},[e._v("Termodynamikens första huvudsats"),t("OutboundLink")],1),e._v(' (energiprincipen) vilken säger att energi varken kan skapas eller förstöras och att värme är en form av energitransport. Ett exempel är ett föremål som faller från en höjd; till en början har det en viss lägesenergi, medan det faller omvandlas lägesenergin till rörelseenergi och när föremålet träffar marken omvandlas rörelseenergin till framförallt värmeenergi (temperaturen ökar) genom yttre och inre friktion. Föremålet (och även nedslagsplatsen) deformeras och denna deformation är vad som återstår av processen sedan värmen avklingat, en möjlig tillämpning av "teknik" (avsiktlig i stället för oavsiktlig deformation) det vill säga överföring av energi.')]),e._v(" "),t("p",[t("a",{attrs:{href:"https://sv.wikipedia.org/wiki/Termodynamikens_andra_huvudsats",target:"_blank",rel:"noopener noreferrer"}},[e._v("Termodynamikens andra huvudsats"),t("OutboundLink")],1),e._v(", som säger att den totala "),t("a",{attrs:{href:"https://sv.wikipedia.org/wiki/Entropi",title:"Entropi",target:"_blank",rel:"noopener noreferrer"}},[e._v("entropin"),t("OutboundLink")],1),e._v(", "),t("em",[e._v("oordningen")]),e._v(", i universum ökar, vilket gör att naturliga processer bara kan ske spontant i en riktning.")]),e._v(" "),t("p",[t("strong",[t("em",[e._v("Se filmen nedan")])])]),e._v(" "),t("iframe",{attrs:{width:"560",height:"315",src:"https://www.youtube-nocookie.com/embed/RLwQcZE5cXw",frameborder:"0",allow:"accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""}}),e._v(" "),t("p",[t("a",{attrs:{href:"https://sv.wikipedia.org/wiki/Termodynamik",title:"Termodynamik",target:"_blank",rel:"noopener noreferrer"}},[e._v("Termodynamikens"),t("OutboundLink")],1),e._v(" "),t("strong",[e._v("tredje huvudsats")]),e._v(" är en statistisk "),t("a",{attrs:{href:"https://sv.wikipedia.org/wiki/Naturlag",title:"Naturlag",target:"_blank",rel:"noopener noreferrer"}},[e._v("naturlag"),t("OutboundLink")],1),e._v(" som behandlar "),t("a",{attrs:{href:"https://sv.wikipedia.org/wiki/Entropi",title:"Entropi",target:"_blank",rel:"noopener noreferrer"}},[e._v("entropin"),t("OutboundLink")],1),e._v(" i ett "),t("a",{attrs:{href:"https://sv.wikipedia.org/wiki/Termodynamiskt_system",title:"Termodynamiskt system",target:"_blank",rel:"noopener noreferrer"}},[e._v("termodynamiskt system"),t("OutboundLink")],1),e._v(":")]),e._v(" "),t("p",[t("em",[e._v("Entropin för en perfekt kristall närmar sig noll då den absoluta temperaturen närmar sig noll.")])]),e._v(" "),t("p",[e._v("**Grundläggande begrepp inom Termodynamik")]),e._v(" "),t("p",[e._v("System**")]),e._v(" "),t("p",[e._v("Ett viktigt koncept inom termodynamiken är det termodynamiska systemet, en avgränsad del av universum under betraktande. Systemet avgränsas från resten av universum, omgivningen, med en fysisk eller hypotetisk gräns. Ett system kan utgöras av vad som helst, exempelvis en turbin, en lösning i ett provrör, en levande organism, en planet, eller något annat.\n")]),e._v(" "),t("p",[t("strong",[e._v("Storhet")]),e._v("\nEn karaktäristisk egenskap hos ett system kallas storhet, exempel på storheter kan vara temperatur T, entropi S, värme Q eller densitet ρ. Storheterna inom termodynamiken delas ofta in i processtorheter och tillståndsstorheter beroende på deras egenskaper vid en process. Storheter som värme och arbete är båda beroende av på vilket sätt en process genomgåtts, det vill säga dess processväg. Tillståndsstorheter som temperatur och tryck är å andra sidan inte vägberoende utan deras storlek bestäms entydigt av systemets tillstånd")]),e._v(" "),t("p",[t("strong",[e._v("Tillstånd")]),e._v("\nOm tillräckligt många tillståndsstorheter är kända i ett system sägs dessa utgöra ett tillstånd. Ett tillstånd är unikt och har bestämda värden på samtliga storheter, om en storhet skulle ändras skulle detta även förändra tillståndet. Om systemet är homogent och tillståndet statiskt sägs systemet vara i jämvikt, detta innebär att om system isoleras från sin omgivning förändras inte värdet på dess storheter. Naturliga system är ofta dynamiska och relativt komplexa men i många fall kan de efterliknas med modeller av system i jämviktstillstånd. Jämvikt kan delas in i en rad underordnade tillstånd som alla måste vara uppfyllda för att system ska kunna antas vara i fullständig jämvikt. Termisk jämvikt innebär att det inte finns någon temperaturdifferens i systemet. Den närliggande vetenskapen värmeöverföring behandlar i princip enbart system som inte är i termisk jämvikt. Kemisk jämvikt innebär att den kemiska sammansättningen i systemet inte förändras med tiden. Mekanisk jämvikt är frånvaro av tryckskillnad inom ett system, vanligtvis bortser man från den tryckskillnad som åstadkoms av gravitationen på grund av höjdskillnad. Om systemet innefattar flera faser krävs även att massan hos dessa faser når jämviktstillstånd.")]),e._v(" "),t("p",[t("strong",[e._v("Process")]),e._v("\nTermodynamisk process är ett begrepp som används för att beskriva den förändring som sker då ett termodynamiskt system övergår från ett tillstånd till ett annat. De tillstånd systemet passerar i en process brukar kallas "),t("em",[e._v("processväg")]),e._v(". För att en process ska vara fullständigt definierad måste både det ursprungliga och slutliga tillståndet beskrivas, såväl som processvägen och den påverkan processen gör på sin omgivningen. Vid modellering av termodynamiska processer brukar man ofta utgå från en så kallad "),t("a",{attrs:{href:"https://sv.wikipedia.org/wiki/Kvasistatisk_process",title:"Kvasistatisk process",target:"_blank",rel:"noopener noreferrer"}},[e._v("kvasistatisk process"),t("OutboundLink")],1),e._v(", i vilken varje processteg sker så långsamt att systemet i stort sett är i ständig jämvikt. Det är dock viktigt att notera att inga sådana processer existerar i verkligheten.")]),e._v(" "),t("p",[t("strong",[e._v("Tillämpning")]),e._v("\nI stort sett alla aktiviteter och processer i naturen involverar på något sätt interaktion mellan materia och energi. Tillämpning av grundläggande termodynamiska principer är därför av stor vikt inom många tekniska och naturvetenskapliga områden; såväl den mänskliga kroppen som kärnkraftverk och jetmotorer måste följa termodynamikens huvudsatser och lagar. Många av de områden där mer avancerad termodynamik behandlas involverar ingenjörer inom kemi- och maskinteknik, exempelvis energiteknik, materialvetenskap och förbränningslära. Nedan beskrivs kort några tillämpade områden inom termodynamiken.")]),e._v(" "),t("p",[e._v("Inom astronomin och kosmologin används termodynamiken för att förklara och förutse stjärnornas egenskaper och utveckling. Gravitationen vill få en stjärna att dra sig samman och öka förbränningstakten medan strålningstrycket vill få den att expandera och därmed svalna. Huvudseriestjärnors värmeproduktion kan med stor noggrannhet beräknas med enkla tvådimensionella datormodeller. Värmeproduktionen i stjärnor som lämnat huvudserien och blivit röda jättar eller som går under i en supernovaexplosion måste beräknas med komplexa tredimensionella modeller som tar hänsyn till bland annat turbulens och magnetfält.")]),e._v(" "),t("p",[e._v("Energiteknik är ett tvärvetenskapligt område som huvudsakligen behandlar produktion av elektricitet och värme. I värmekraftverk används höga temperaturer från exempelvis förbränning eller kärnklyvning för att via en turbin generera elektricitet. I ett kraftvärmeverk sker samtida produktion av elektricitet och värme. En majoritet av världens elproduktion sker i kraftverk av de här typerna där fossila bränslen, biomassa eller kärnbränsle används för att skapa höga temperaturer.")]),e._v(" "),t("p",[e._v("Inom transportindustrin är förbränningsmotorer, och då särskilt kolvmotorer, ett stort tillämpningsområde. Genom kompression av luft och förbränning av kolväten som diesel, metan eller bensin drivs motorns kolvar att producera mekaniskt arbete som kan användas för att driva en bil, båt eller annat transportmedel. Otto- och dieselcyklerna är exempel där termodynamiska kretsprocesser kan användas för att modellera arbetsförloppet i en verklig motor.")]),e._v(" "),t("p",[e._v("Kyl- och värmeteknik bygger på att motverka det faktum att värme flödar från en hög temperatur till en låg, ett uttryck för termodynamikens andra huvudsats. I många fall är det önskvärt att hålla en konstant hög eller låg temperatur i ett visst utrymme, exempelvis i ett kylskåp eller ett bostadshus, vilket kan åstadkommas med en så kallad värmepump. Värmepumpar flyttar värme från ett område med låg temperatur till ett område med högre temperatur och motverkar på så vis det naturliga värmeflödet.")]),e._v(" "),t("p",[e._v("Materialvetenskap tillämpar termodynamiken för att avgöra hur material agerar och reagerar vid olika förhållanden. Ett användningsområde är fasdiagram, vilket beskriver hur ett ämne beter sig vid olika tillstånd. Detta tillsammans med ämnets värmeabsorberande förmåga, dess värmekapacitet, är grundläggande och vitala kunskaper för att beskriva de kemiska och termiska egenskaperna hos material. Med hjälp av bland annat Gibbs fria energi går det även att avgöra hur potenta olika reaktioner inom och mellan material är.")]),e._v(" "),t("p",[e._v("Fält som bioteknik, medicinsk vetenskap och molekylärbiologi använder principer från den klassiska och statistiska termodynamiken för att beskriva allt från organ som hjärtat till enskilda enzymer och proteiner. Med hjälp av termodynamisk analys kan man förstå molekylära mekanismer hos en lång rad biologiska funktioner som enzymatisk katalys, signaltransduktion och genduplikation. Inom medicinen kan entalpiskillnader mellan frisk och sjuk vävnad användas för att mäta aktiviteten hos olika former av cancer.")]),e._v(" "),t("p",[e._v("Inom meteorologin utnyttjas atmosfärens termodynamik, värmeöverföring och strömningslära för att beskriva och förutse olika typer av väderfenomen. Ett viktigt exempel på tillämpning är studiet av stormar, orkaner och tropiska cykloner. En tropisk cyklon kan modelleras som en värmemotor driven av atmosfärens temperaturskillnad. Varm fuktig luft stiger varvid den expanderar och kondenseras, vilket leder till att stora mängder latent värme frigörs och kan omvandlas till kinetisk energi i stormen")])])},[],!1,null,null,null);r.default=a.exports}}]);